{"command":"set +e
rm -f /tmp/py.{json,csv,md,adoc,org}
python3 hyperfine.py --style basic -r 2 --export-json /tmp/py.json --export-csv /tmp/py.csv --export-markdown /tmp/py.md --export-asciidoc /tmp/py.adoc --export-orgmode /tmp/py.org 'sleep 0.01' 'sleep 0.02' > /tmp/pyout 2>/tmp/pyerr
rc=$?; echo rc=$rc; cat /tmp/pyout; cat /tmp/pyerr
for f in /tmp/py.json /tmp/py.csv /tmp/py.md /tmp/py.adoc /tmp/py.org; do echo ---$f---; cat $f; done"}
